import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target = inputs["target_state"].copy()
    events = inputs["cdc_events"].copy()

    # 1. Deduplicate events delivered more than once (same seq) -> apply once.
    events = events.drop_duplicates(subset=["seq"], keep="first")

    # Build current state (mutable) and remember original last_seq for the
    # replay guard (the guard is evaluated against the *original*
    # target_state, not the evolving in-batch state).
    state = {}
    orig_last_seq = {}
    for _, row in target.iterrows():
        oid = int(row["order_id"])
        state[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": int(row["last_seq"]),
        }
        orig_last_seq[oid] = int(row["last_seq"])

    # Orders that ever had a row (from target_state or created in this batch).
    has_had_row = set(state.keys())

    last_event_op = {}
    last_event_seq = {}

    # 2/3. Process remaining events strictly in seq order, per order.
    events_sorted = events.sort_values(["order_id", "seq"], kind="mergesort")

    for _, ev in events_sorted.iterrows():
        oid = int(ev["order_id"])
        seq = int(ev["seq"])
        op = ev["op"]
        status = ev["status"]
        amount = ev["amount"]

        # Replay guard: only applies if the order had a row in the
        # ORIGINAL target_state, compared against that original last_seq.
        if oid in orig_last_seq and seq <= orig_last_seq[oid]:
            continue

        if op in ("I", "U"):
            if oid in state:
                state[oid]["status"] = status
                if op == "U" and pd.isna(amount):
                    # 'U' with NULL amount leaves existing amount unchanged.
                    pass
                else:
                    state[oid]["amount"] = amount
                state[oid]["last_seq"] = seq
            else:
                state[oid] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                }
            has_had_row.add(oid)
            # I/U always has an effect (creates or updates the row).
            last_event_op[oid] = op
            last_event_seq[oid] = seq
        elif op == "D":
            if oid in state:
                # Row existed: deletion has an effect, record it.
                del state[oid]
                last_event_op[oid] = op
                last_event_seq[oid] = seq
            # A 'D' on a missing order does nothing to the state, and is
            # NOT considered an "applied" event for tombstone purposes
            # (it leaves no trace, so it must not override the last
            # genuinely-effective event).

    # Build new_state output.
    if state:
        new_rows = [
            {
                "order_id": oid,
                "status": s["status"],
                "amount": s["amount"],
                "last_seq": s["last_seq"],
            }
            for oid, s in state.items()
        ]
        new_state = pd.DataFrame(new_rows)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    new_state = new_state.reindex(columns=["order_id", "status", "amount", "last_seq"])
    new_state["order_id"] = new_state["order_id"].astype("int64")
    new_state["last_seq"] = new_state["last_seq"].astype("int64")
    new_state["amount"] = new_state["amount"].astype("float64")
    new_state["status"] = new_state["status"].astype(object)

    # Build tombstones output.
    tomb_rows = []
    for oid, op in last_event_op.items():
        if op == "D" and oid in has_had_row:
            tomb_rows.append({"order_id": oid, "deleted_seq": last_event_seq[oid]})

    if tomb_rows:
        tombstones = pd.DataFrame(tomb_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    tombstones = tombstones.reindex(columns=["order_id", "deleted_seq"])
    tombstones["order_id"] = tombstones["order_id"].astype("int64")
    tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {"new_state": new_state, "tombstones": tombstones}
